## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/chronicPancreatitisLogic.ts`

```typescript
/**
 * Chronic Pancreatitis Clinical Logic Engine
 * Based on: ASGE Guideline on Endoscopic Therapy for Chronic Pancreatitis (2020, 2024 Update)
 *           APA/IAP Guidelines on Chronic Pancreatitis (2017, 2024 Update)
 *           ACG Clinical Guideline: Chronic Pancreatitis (2020)
 *           ESGE Guideline on Endoscopic Treatment of Chronic Pancreatitis (2023)
 * Key decisions: Endoscopic vs surgical drainage, ESWL, pain management,
 *                exocrine/endocrine insufficiency, pseudocyst drainage
 */

export type PainPattern = 'type_a' | 'type_b' | 'painless';
// Type A: short intermittent pain episodes; Type B: continuous/persistent pain

export type EtiologyCP =
  | 'alcohol'
  | 'smoking'
  | 'idiopathic'
  | 'hereditary_genetic' // PRSS1, SPINK1, CFTR, CTRC
  | 'autoimmune_type1' // IgG4-related
  | 'autoimmune_type2'
  | 'obstructive' // Stricture, tumor, divisum
  | 'metabolic' // Hypercalcemia, hypertriglyceridemia
  | 'post_necrotizing_pancreatitis';

export type PancreaticDuctAnatomy =
  | 'normal'
  | 'dilated_without_stricture' // MPD ≥5mm without dominant stricture
  | 'dilated_with_stricture' // MPD ≥5mm + dominant stricture
  | 'stones_without_stricture'
  | 'stones_with_stricture'
  | 'divisum' // Pancreas divisum
  | 'disrupted_duct'; // Disconnected pancreatic duct syndrome

export interface ChronicPancreatitisInput {
  // Diagnosis
  diagnosisConfirmed: boolean;
  diagnosisMethod: 'imaging' | 'eus_criteria' | 'mrcp' | 'ercp' | 'histology' | 'clinical';
  cambridgeGrade?: 'I' | 'II' | 'III' | 'IV'; // Cambridge classification on imaging
  eusRosedaleCriteria?: number; // 0–9 Rosedale score (≥4 = definite CP)

  // Etiology
  etiology: EtiologyCP;
  alcoholGramsPerDay?: number;
  isSmoker: boolean;
  hasGeneticMutation: boolean;
  geneticMutation?: string; // PRSS1, SPINK1, CFTR
  igg4Level?: number; // >135 mg/dL = autoimmune type 1

  // Pain
  painPattern: PainPattern;
  vasScore?: number; // 0–10 visual analog scale
  hasPainRelatedHospitalizations: boolean;
  isOnOpioids: boolean;
  opioidDoseEquivalent?: number; // morphine mg equivalent/day

  // Pancreatic duct
  ductAnatomy: PancreaticDuctAnatomy;
  mpdDiameterMm?: number;
  hasStones: boolean;
  stoneSizeMm?: number;
  stoneLocation?: 'head' | 'body' | 'tail' | 'multiple';
  hasCalcifications: boolean;
  hasStricture: boolean;
  strictureLocation?: 'head' | 'body' | 'tail';

  // Complications
  hasPseudocyst: boolean;
  pseudocystSizeCm?: number;
  pseudocystSymptoms?: 'none' | 'pain' | 'compression' | 'infected';
  hasBiliaryStenosis: boolean;
  hasDuodenalObstruction: boolean;
  hasSplenicVeinThrombosis: boolean;
  hasPancreaticFistula: boolean;
  hasPancreaticAscites: boolean;
  suspectedMalignancy: boolean; // CP increases pancreatic cancer risk 13x

  // Exocrine insufficiency
  hasExocrineInsufficiency: boolean;
  hasSteatorrhea: boolean;
  hasMalnutrition: boolean;
  isOnPERT: boolean; // Pancreatic enzyme replacement therapy

  // Endocrine insufficiency
  hasType3cDiabetes: boolean; // Pancreatogenic diabetes
  hba1cPercent?: number;
  isOnInsulin: boolean;

  // Prior interventions
  hasPriorERCP: boolean;
  hasPriorESWL: boolean; // Extracorporeal shock wave lithotripsy
  hasPriorSurgery: boolean;
  priorSurgeryType?: 'puestow' | 'frey' | 'beger' | 'whipple' | 'distal_pancreatectomy' | 'other';
  hasPriorEndoscopicDrainage: boolean;
  endoscopicDrainageResponse?: 'good' | 'partial' | 'none';

  // Patient factors
  ageYears: number;
  isSurgicalCandidate: boolean;
  performanceStatus: 'good' | 'moderate' | 'poor';
}

export interface ChronicPancreatitisRecommendation {
  primaryRecommendation: string;
  painManagement: string;
  endoscopicTherapy: string;
  surgicalConsideration: string;
  pseudocystManagement: string;
  exocrineSupportPlan: string;
  endocrineSupportPlan: string;
  malignancySurveillance: string;
  lifestyleModification: string;
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessChronicPancreatitis(input: ChronicPancreatitisInput): ChronicPancreatitisRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.suspectedMalignancy) {
    urgentFlags.push('Suspected malignancy in chronic pancreatitis: EUS-FNB + CT staging required — pancreatic cancer risk 13x higher in CP. Multidisciplinary tumor board review.');
  }
  if (input.hasPseudocyst && input.pseudocystSymptoms === 'infected') {
    urgentFlags.push('Infected pancreatic pseudocyst: IV antibiotics + urgent drainage (EUS-guided preferred) — risk of sepsis');
  }
  if (input.hasDuodenalObstruction) {
    urgentFlags.push('Duodenal obstruction: surgical or endoscopic bypass required — gastrojejunostomy or EUS-guided gastroenterostomy');
  }
  if (input.hasBiliaryStenosis) {
    urgentFlags.push('Biliary stenosis in CP: ERCP with SEMS placement or surgical biliary bypass — monitor for secondary biliary cirrhosis');
  }
  if (input.hasSplenicVeinThrombosis) {
    urgentFlags.push('Splenic vein thrombosis: risk of gastric varices and bleeding — anticoagulation discussion + splenectomy if bleeding');
  }
  if (input.igg4Level !== undefined && input.igg4Level > 135) {
    urgentFlags.push(`IgG4 ${input.igg4Level} mg/dL (>135): autoimmune pancreatitis type 1 — trial of prednisone 40mg/day x4 weeks before invasive intervention`);
    nextSteps.push('Prednisone 40mg/day x4 weeks (autoimmune pancreatitis type 1)', 'Repeat imaging after steroid trial');
  }

  // ─── Pain Management ──────────────────────────────────────────────────────
  const painManagement =
    'PAIN MANAGEMENT (APA/IAP 2024 — stepwise approach): ' +
    '1) LIFESTYLE: alcohol and smoking cessation — most important modifiable factors. ' +
    '   Smoking cessation reduces pain and slows disease progression. ' +
    '2) ANALGESICS: ' +
    '   Step 1: Non-opioid (acetaminophen, NSAIDs — caution with renal function). ' +
    '   Step 2: Weak opioids (tramadol, codeine). ' +
    '   Step 3: Strong opioids (oxycodone, morphine) — last resort; risk of addiction. ' +
    '3) ADJUVANT: ' +
    '   Pregabalin/gabapentin: neuropathic pain component. ' +
    '   Antidepressants (duloxetine, amitriptyline): central sensitization. ' +
    '   Pancreatic enzyme replacement (PERT): may reduce pain via CCK feedback (controversial). ' +
    '4) ENDOSCOPIC/INTERVENTIONAL: ' +
    '   EUS-guided celiac plexus block: short-term pain relief (3–6 months). ' +
    '   Endoscopic pancreatic duct decompression: for obstructive pain. ' +
    (input.isOnOpioids
      ? `Current opioid dose: ${input.opioidDoseEquivalent ?? 'unknown'} MME/day. Consider opioid rotation or pain specialist referral. `
      : '');

  // ─── Endoscopic Therapy ───────────────────────────────────────────────────
  let endoscopicTherapy = '';
  const isEndoscopicCandidate =
    input.ductAnatomy === 'dilated_with_stricture' ||
    input.ductAnatomy === 'stones_with_stricture' ||
    input.ductAnatomy === 'stones_without_stricture' ||
    input.ductAnatomy === 'dilated_without_stricture';

  if (isEndoscopicCandidate) {
    endoscopicTherapy =
      'ENDOSCOPIC THERAPY (ASGE 2024 / ESGE 2023): ' +
      '1) ERCP + PANCREATIC DUCT STENTING: ' +
      '   Indication: dominant stricture with upstream MPD dilation (≥5mm). ' +
      '   Technique: sphincterotomy + stricture dilation + plastic stent (7–10Fr). ' +
      '   Multiple plastic stents (ESGE 2023): superior to single stent — 3–4 stents side-by-side. ' +
      '   Stent exchange every 3–6 months x12 months → assess for stricture resolution. ' +
      '   Fully covered SEMS (FCSEMS): emerging — better stricture resolution than multiple plastic stents (RESPONDER trial). ' +
      '2) ESWL (Extracorporeal Shock Wave Lithotripsy): ' +
      '   Indication: pancreatic duct stones >5mm preventing endoscopic clearance. ' +
      '   Fragmentation of stones → ERCP for clearance. ' +
      '   ESWL + ERCP: 70–80% stone clearance. ' +
      '   ESWL alone: effective for fragmentation without subsequent ERCP in select cases. ' +
      '3) PANCREATOSCOPY (SpyGlass): ' +
      '   Direct visualization of duct + laser/EHL lithotripsy for refractory stones. ' +
      '   Reserved for stones not amenable to ESWL. ' +
      '4) EUS-GUIDED CELIAC PLEXUS BLOCK: ' +
      '   Short-term pain relief (3–6 months). ' +
      '   Repeat as needed. Less effective than in pancreatic cancer.';
    nextSteps.push('ERCP with pancreatic sphincterotomy and stent placement', 'ESWL if stones >5mm preventing endoscopic access');
  } else if (input.ductAnatomy === 'divisum') {
    endoscopicTherapy =
      'PANCREAS DIVISUM (ASGE 2024): ' +
      'Minor papilla sphincterotomy + dorsal duct stenting for symptomatic divisum. ' +
      'Technical success: 80–90%. Clinical success: 50–70%. ' +
      'Surgical minor papilla sphincteroplasty if endoscopic therapy fails.';
    nextSteps.push('Minor papilla sphincterotomy + dorsal duct stenting');
  } else if (input.ductAnatomy === 'disrupted_duct') {
    endoscopicTherapy =
      'DISCONNECTED PANCREATIC DUCT SYNDROME (DPDS): ' +
      'Transmural drainage (EUS-guided) with LAMS — creates fistula for sustained drainage. ' +
      'Transpapillary stenting (ERCP) if duct continuity preserved. ' +
      'Surgical resection for refractory DPDS.';
    nextSteps.push('EUS-guided transmural drainage with LAMS for disconnected duct syndrome');
  } else {
    endoscopicTherapy =
      'Endoscopic therapy not indicated for current duct anatomy. ' +
      'Medical management and lifestyle modification are the focus. ' +
      'Reassess if pain worsens or duct anatomy changes.';
  }

  // ─── Surgical Consideration ───────────────────────────────────────────────
  let surgicalConsideration = '';
  if (input.isSurgicalCandidate) {
    surgicalConsideration =
      'SURGICAL OPTIONS (APA/IAP 2024 — surgery superior to endoscopy for long-term pain relief): ' +
      '1) LATERAL PANCREATICOJEJUNOSTOMY (Puestow/Partington-Rochelle): ' +
      '   Indication: dilated MPD ≥7mm without dominant head mass. ' +
      '   Long-term pain relief: 70–80% at 5 years. ' +
      '   ESCAPE trial (2020): surgery superior to endoscopy for pain at 18 months. ' +
      '2) DUODENUM-PRESERVING PANCREATIC HEAD RESECTION (Frey/Beger): ' +
      '   Indication: inflammatory head mass ("head of the worm") + dilated duct. ' +
      '   Preserves duodenum — lower morbidity than Whipple. ' +
      '3) PANCREATICODUODENECTOMY (Whipple): ' +
      '   Indication: cannot exclude malignancy, dominant head mass, failed Frey/Beger. ' +
      '4) TOTAL PANCREATECTOMY + ISLET AUTOTRANSPLANTATION (TP-IAT): ' +
      '   Indication: hereditary/genetic CP, refractory pain, failed all other interventions. ' +
      '   Preserves insulin secretion (islet autotransplantation). ' +
      '   Best outcomes when performed before diabetes develops.';
    if (!input.hasPriorEndoscopicDrainage || input.endoscopicDrainageResponse === 'none') {
      nextSteps.push('Surgical consultation for lateral pancreaticojejunostomy (Puestow) or Frey procedure');
    }
  } else {
    surgicalConsideration = 'Patient not surgical candidate — optimize endoscopic and medical management. Reassess surgical candidacy after optimization.';
  }

  // ─── Pseudocyst Management ────────────────────────────────────────────────
  let pseudocystManagement = 'No pseudocyst identified.';
  if (input.hasPseudocyst) {
    if (input.pseudocystSymptoms === 'none' && (input.pseudocystSizeCm === undefined || input.pseudocystSizeCm < 6)) {
      pseudocystManagement =
        'Asymptomatic pseudocyst <6cm: observation. ' +
        'MRI/MRCP every 3–6 months. ' +
        'Many resolve spontaneously (30–40% within 6 weeks).';
    } else if (input.pseudocystSymptoms !== 'none' || (input.pseudocystSizeCm !== undefined && input.pseudocystSizeCm >= 6)) {
      pseudocystManagement =
        'Symptomatic or large (≥6cm) pseudocyst: drainage indicated. ' +
        '1) EUS-GUIDED TRANSMURAL DRAINAGE (preferred): ' +
        '   LAMS (Hot AXIOS) or double-pigtail plastic stents. ' +
        '   Technical success: 92–97%. Clinical success: 85–92%. ' +
        '   Preferred over surgical or percutaneous drainage. ' +
        '2) TRANSPAPILLARY DRAINAGE (ERCP): if duct communication present. ' +
        '3) Surgical cystgastrostomy: if EUS drainage fails or anatomy unfavorable.';
      nextSteps.push('EUS-guided pseudocyst drainage with LAMS or double-pigtail stents');
    }
  }

  // ─── Exocrine Support ─────────────────────────────────────────────────────
  const exocrineSupportPlan =
    input.hasExocrineInsufficiency || input.hasSteatorrhea
      ? 'PANCREATIC EXOCRINE INSUFFICIENCY (PEI): ' +
        'PERT (Pancreatic Enzyme Replacement Therapy): ' +
        'Starting dose: 40,000–50,000 lipase units per main meal; 25,000 units per snack. ' +
        'Titrate up to 75,000–80,000 lipase units per meal if inadequate response. ' +
        'Take with FIRST bite of food. ' +
        'Brands: Creon, Zenpep, Pancreaze, Viokace (non-enteric coated — use with PPI). ' +
        'Add PPI (omeprazole 20–40mg) if inadequate response — gastric acid inactivates enzymes. ' +
        'Monitor: fat-soluble vitamins (A, D, E, K), B12, zinc. ' +
        'Nutritional support: dietitian referral; medium-chain triglycerides (MCT) supplements.'
      : 'No exocrine insufficiency identified. Monitor for development — annual fecal elastase-1 if at risk.';

  // ─── Endocrine Support ────────────────────────────────────────────────────
  const endocrineSupportPlan =
    input.hasType3cDiabetes
      ? 'TYPE 3c DIABETES (Pancreatogenic Diabetes): ' +
        'Distinct from T1DM and T2DM — loss of both alpha and beta cells. ' +
        'Hypoglycemia risk is HIGH (glucagon deficiency). ' +
        'Treatment: ' +
        '1) Insulin (preferred): basal-bolus regimen. Start low, titrate carefully. ' +
        '2) Metformin: may be used if residual beta-cell function. ' +
        '3) GLP-1 agonists: use with caution — may worsen exocrine insufficiency. ' +
        '4) Avoid sulfonylureas — high hypoglycemia risk. ' +
        'Endocrinology referral recommended. ' +
        'Continuous glucose monitoring (CGM) for hypoglycemia detection.'
      : 'No diabetes identified. Annual HbA1c and fasting glucose monitoring recommended (CP increases T3cDM risk).';

  // ─── Malignancy Surveillance ──────────────────────────────────────────────
  const malignancySurveillance =
    'PANCREATIC CANCER SURVEILLANCE in CP (APA 2024): ' +
    'CP increases pancreatic cancer risk 13–16x (hereditary CP: 50–70x). ' +
    'Annual MRI/MRCP or EUS for: hereditary/genetic CP (PRSS1, SPINK1, CFTR), CP duration >20 years, new-onset diabetes in CP. ' +
    'Alarm features requiring immediate workup: new/worsening pain, weight loss, new-onset DM, rising CA 19-9. ' +
    'EUS-FNB if solid mass detected.';

  // ─── Lifestyle Modification ───────────────────────────────────────────────
  const lifestyleModification =
    'LIFESTYLE MODIFICATION (cornerstone — APA/IAP 2024): ' +
    '1) ALCOHOL CESSATION: most important — reduces pain and slows progression. ' +
    '   Alcohol abstinence counseling + referral to addiction medicine. ' +
    '2) SMOKING CESSATION: independent risk factor for CP progression and pancreatic cancer. ' +
    '3) LOW-FAT DIET: reduces stimulation of pancreatic secretion. ' +
    '4) SMALL FREQUENT MEALS: 4–6 small meals/day. ' +
    '5) ANTIOXIDANTS: vitamin C, E, selenium, methionine — modest pain benefit (controversial). ' +
    '6) HYDRATION: adequate fluid intake.';

  if (nextSteps.length === 0) {
    nextSteps.push(
      'Alcohol and smoking cessation counseling',
      'PERT initiation if exocrine insufficiency',
      'ERCP evaluation for ductal anatomy and stenting',
      'EUS for celiac plexus block if pain refractory to medical management',
      'Surgical consultation if endoscopic therapy fails'
    );
  }

  const rationale =
    `Etiology: ${input.etiology.replace(/_/g, ' ')}. ` +
    `Pain pattern: ${input.painPattern.replace(/_/g, ' ')}. ` +
    `Duct anatomy: ${input.ductAnatomy.replace(/_/g, ' ')}. ` +
    `MPD diameter: ${input.mpdDiameterMm ? `${input.mpdDiameterMm}mm` : 'not measured'}. ` +
    `Stones: ${input.hasStones ? 'Yes' : 'No'}. ` +
    `Exocrine insufficiency: ${input.hasExocrineInsufficiency ? 'Yes' : 'No'}. ` +
    `Type 3c DM: ${input.hasType3cDiabetes ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      input.suspectedMalignancy
        ? 'Suspected malignancy in chronic pancreatitis: EUS-FNB + CT staging required urgently.'
        : input.igg4Level !== undefined && input.igg4Level > 135
        ? 'Autoimmune pancreatitis type 1 (IgG4 >135): prednisone trial before invasive intervention.'
        : input.hasPseudocyst && input.pseudocystSymptoms === 'infected'
        ? 'Infected pseudocyst: urgent EUS-guided drainage + IV antibiotics.'
        : isEndoscopicCandidate
        ? 'Obstructive chronic pancreatitis: ERCP with pancreatic duct stenting ± ESWL for stones.'
        : 'Chronic pancreatitis: alcohol/smoking cessation + pain management + PERT if exocrine insufficiency.',
    painManagement,
    endoscopicTherapy,
    surgicalConsideration,
    pseudocystManagement,
    exocrineSupportPlan,
    endocrineSupportPlan,
    malignancySurveillance,
    lifestyleModification,
    urgentFlags,
    nextSteps,
    evidenceLevel: 'B',
    rationale,
    references: [
      {
        citation: 'Löhr JM, et al. United European Gastroenterology Evidence-Based Guidelines for the Diagnosis and Therapy of Chronic Pancreatitis. United European Gastroenterol J. 2017;5(2):153-199.',
        pmid: '28344786',
        url: 'https://pubmed.ncbi.nlm.nih.gov/28344786/',
      },
      {
        citation: 'Issa Y, et al. Effect of Early Surgery vs Endoscopy-First Approach on Pain in Patients with Chronic Pancreatitis (ESCAPE). JAMA. 2020;323(3):237-247.',
        pmid: '31961409',
        url: 'https://pubmed.ncbi.nlm.nih.gov/31961409/',
      },
      {
        citation: 'Dumonceau JM, et al. Endoscopic Treatment of Chronic Pancreatitis: European Society of Gastrointestinal Endoscopy (ESGE) Guideline. Endoscopy. 2023;55(12):1124-1145.',
        pmid: '37797618',
        url: 'https://pubmed.ncbi.nlm.nih.gov/37797618/',
      },
      {
        citation: 'Gardner TB, et al. ACG Clinical Guideline: Chronic Pancreatitis. Am J Gastroenterol. 2020;115(3):322-339.',
        pmid: '32022720',
        url: 'https://pubmed.ncbi.nlm.nih.gov/32022720/',
      },
    ],
  };
}
